def decode_log_info(log):
    import re
    try:
        if not isinstance(log, str):
            return None
        # Match: LOG_LEVEL[TIMESTAMP] : MESSAGE
        pattern = r'^([A-Za-z_]+)\[([^\]]+)\]\s*:\s*(.*)$'
        m = re.match(pattern, log, re.DOTALL)
        if not m:
            return None
        log_level = m.group(1)
        timestamp = m.group(2)
        message = m.group(3)
        return (log_level, timestamp, message)
    except Exception:
        return None

