def verify_user_email(email_input: str) -> bool:
    """
    Validate an email address format and reject addresses from risky domains.

    Returns True if the email looks valid per valid_email_pattern and its domain
    does not end with any suffix in RISKY_DOMAINS. Otherwise returns False.
    """
    try:
        if not isinstance(email_input, str):
            return False

        # Decode any percent-encoding and remove surrounding whitespace
        email = unquote(email_input).strip()

        # Basic format check using provided regex
        if not valid_email_pattern.match(email):
            return False

        # Extract domain part and check against risky domain suffixes
        parts = email.rsplit('@', 1)
        if len(parts) != 2:
            return False
        domain = parts[1].lower()

        for suffix in RISKY_DOMAINS:
            if domain.endswith(suffix):
                return False

        return True

    except Exception:
        return False

