def generate_patient_summary(patient_id: str, report_template: str) -> str:
    """
    Fill a report template with patient information.

    Raises ValueError if:
    - patient_id is not found
    - the template attempts to access restricted medical data (diagnosis, treatment_plan)
    - the template references a non-existent patient attribute
    """
    if patient_id not in patients_data:
        raise ValueError(f"Invalid patient ID: {patient_id}")

    patient = patients_data[patient_id]
    restricted_attrs = {"diagnosis", "treatment_plan"}

    # Find placeholders like {patient.name}, {patient.age}, etc.
    pattern = re.compile(r'\{patient\.([a-zA-Z_][a-zA-Z0-9_]*)\}')

    def _replace(match):
        attr = match.group(1)
        if attr in restricted_attrs:
            raise ValueError(f"Attempt to access restricted medical data: '{attr}'")
        if not hasattr(patient, attr):
            raise ValueError(f"Patient has no attribute '{attr}'")
        return str(getattr(patient, attr))

    # Perform substitutions
    return pattern.sub(_replace, report_template)

