def assemble_employee_list(dept_name: str, template: str) -> str:
    """
    Assemble a formatted employee directory for the given department by replacing
    placeholders like '{employee.name}' and '{employee.position}' in the template.

    Raises ValueError if the template attempts to access restricted fields (salary,
    personal_email) or tries to access invalid/unexpected attributes, or if an
    unexpected error occurs.
    """
    # Regex to find occurrences like {employee.attr}
    pattern = re.compile(r'\{employee\.([A-Za-z_]\w*)\}')

    results = []

    for emp in employees:
        if emp.department != dept_name:
            continue

        def _replace(match):
            attr = match.group(1)

            # Block access to private/magic attributes or suspicious patterns
            if attr.startswith('_') or '__' in attr:
                raise ValueError("Access to restricted or invalid attributes is not allowed.")

            # Block restricted fields explicitly
            if attr in ('salary', 'personal_email'):
                raise ValueError("Access to restricted fields is not allowed.")

            # Ensure attribute exists on the Employee object
            if not hasattr(emp, attr):
                raise ValueError(f"Unexpected field requested: {attr}")

            value = getattr(emp, attr)
            return str(value)

        try:
            formatted = pattern.sub(_replace, template)
            results.append(formatted)
        except ValueError:
            # Propagate expected ValueErrors about restricted access or invalid fields
            raise
        except Exception as exc:
            # Convert unexpected exceptions into ValueError as required
            raise ValueError("An unexpected error occurred.") from exc

    return "\n".join(results)

