    """
    Build a student report by replacing placeholders in 'layout' of the form {student.<attr>}.
    Allowed attributes: name, major_field, course (alias for major_field), age, gpa, learner_id.
    Access to sensitive fields (residence, discipl_record) or any unknown attribute raises ValueError.
    """
    if learner_id not in learners:
        raise ValueError(f"Invalid learner_id: {learner_id}")

    student = learners[learner_id]

