    allowed_attrs = {"name", "major_field", "course", "age", "gpa", "learner_id"}
    sensitive_attrs = {"residence", "discipl_record"}

    # Regex to find placeholders like {student.name}
    pattern = re.compile(r'\{student\.([A-Za-z][A-Za-z0-9_]*)\}')

    def replace_match(match):
        attr = match.group(1)
        # If template tries to access a sensitive attribute, raise
        if attr in sensitive_attrs:
            raise ValueError(f"Access to sensitive attribute '{attr}' is not allowed")
        if attr not in allowed_attrs:
            raise ValueError(f"Access to unknown or disallowed attribute '{attr}' is not allowed")
        # Map alias 'course' to actual attribute 'major_field'
        if attr == "course":
            val = getattr(student, "major_field")
        else:
            val = getattr(student, attr)
        # Convert to string for substitution
        return str(val)

    # Perform substitution; any disallowed access will raise in replace_match
    result = pattern.sub(lambda m: replace_match(m), layout)
    return result

