def create_dynamic_template(html_template, placeholders_input):
    """
    Replace placeholders in an HTML template with escaped values from placeholders_input.

    Placeholders are expected in the form {{name}} where name contains letters, digits or underscores.

    Args:
        html_template (str): HTML template containing placeholders.
        placeholders_input (dict): Mapping from placeholder names to values to insert.

    Returns:
        str: Final HTML string with placeholders replaced by escaped values.

    Raises:
        ValueError: If input types are invalid, a placeholder is missing from placeholders_input,
                    or a regex processing error occurs.
    """
    if not isinstance(html_template, str):
        raise ValueError("html_template must be a string")
    if not isinstance(placeholders_input, dict):
        raise ValueError("placeholders_input must be a dict")

    # Placeholder pattern: {{name}} where name is one or more word chars (letters, digits, underscore)
    pattern = re.compile(r'\{\{([A-Za-z0-9_]+)\}\}')

    def _replace(match):
        key = match.group(1)
        if key not in placeholders_input:
