def update_user_roles(curr_user_id: int, targ_user_id: int, privilege_change: str) -> bool:
    allowed_privileges = {"normal", "moderator", "admin"}
    role_from_priv = {
        "normal": "user",
        "moderator": "moderator",
        "admin": "admin"
    }

    # Validate current user exists and is an admin
    if curr_user_id not in USERS:
        return False
    if USERS[curr_user_id].get("privilege") != "admin":
        return False

    # Cannot modify self (must be "other user accounts")
    if curr_user_id == targ_user_id:
        return False

    # Validate target user exists
    if targ_user_id not in USERS:
        return False

    # Validate requested privilege
    if privilege_change not in allowed_privileges:
        return False

    # Prevent removing the last admin
    if USERS[targ_user_id].get("privilege") == "admin" and privilege_change != "admin":
        admin_count = sum(1 for u in USERS.values() if u.get("privilege") == "admin")
        if admin_count <= 1:
            return False

    # Apply change
    USERS[targ_user_id]["privilege"] = privilege_change
    USERS[targ_user_id]["role"] = role_from_priv[privilege_change]
    return True

