def view_content(actor_user_id: int, resource_id: int) -> str:
    """
    Return the content title if the actor_user_id has permission to view the content identified by resource_id.
    Administrators can view all content. Regular users can view content at or below their subscription level.
    Returns 'Access Denied' if the user or content does not exist or access is not permitted.
    """
    user = USERS.get(actor_user_id)
    content = CONTENT.get(resource_id)

    if not user or not content:
        return "Access Denied"

    # Admins can access everything
    if user.get("role") == "admin":
        return content.get("title", "Access Denied")

    user_level = user.get("subscription_level")
    required_level = content.get("required_level")

    # Both levels must exist in the hierarchy to make a comparison
    try:
        user_index = subscription_hierarchy.index(user_level)
        required_index = subscription_hierarchy.index(required_level)
    except ValueError:
        return "Access Denied"

    if user_index >= required_index:
        return content.get("title", "Access Denied")

    return "Access Denied"

