def modify_employee_profile(worker: dict, changes: dict, is_privileged: bool) -> dict:
    """
    Modify an employee profile according to allowed fields.

    - worker: existing employee profile dict
    - changes: dict of field -> new value
    - is_privileged: if True, apply all changes; otherwise only apply fields in EDITABLE_FIELDS

    Returns a new dict with the applied updates.
    """
    # Work on a shallow copy so the original dict is not modified unexpectedly.
    updated = worker.copy()

    if is_privileged:
        # Privileged users may change any field.
        for key, value in changes.items():
            updated[key] = value
    else:
        # Non-privileged users may only change allowed fields.
        for key, value in changes.items():
            if key in EDITABLE_FIELDS:
                updated[key] = value

    return updated

