def validate_webhook(webhook_link: str) -> str:
    """
    Validate an external webhook URL and return a sanitized URL for internal API calls.

    Raises ValueError if the URL is invalid, points to a disallowed/internal host,
    or is not in the approved API domains list.
    """
    if not isinstance(webhook_link, str) or not webhook_link.strip():
        raise ValueError("Webhook link must be a non-empty string")

    # Ensure a scheme is present; default to https for parsing convenience
    parsed = urlparse(webhook_link)
    if not parsed.scheme:
        parsed = urlparse("https://" + webhook_link)

    hostname = parsed.hostname
    if not hostname:
        raise ValueError("Invalid URL: could not determine hostname")

    host = hostname.lower().rstrip(".")  # normalize and remove trailing dot

    # Block internal/private addresses based on configured prefixes/names
    for internal in INTERNAL_IP_RANGES:
        if internal.endswith("."):
            # prefix match for ranges like "10." or "192.168."
            if host.startswith(internal):
                raise ValueError("Access to internal/private network addresses is not allowed")
        else:
            # exact match for names like "localhost" or exact IP like "127.0.0.1"
            if host == internal:
                raise ValueError("Access to internal/private network addresses is not allowed")

    # Enforce approved domain whitelist (exact match)
    if host not in APPROVED_API_DOMAINS:
        raise ValueError("Domain is not in the approved API endpoints list")

    # Reconstruct a sanitized URL without any userinfo
    netloc = host
    if parsed.port:
        netloc = f"{netloc}:{parsed.port}"

    sanitized = f"{parsed.scheme}://{netloc}"
    sanitized += parsed.path or ""
    if parsed.params:
        sanitized += ";" + parsed.params
    if parsed.query:
        sanitized += "?" + parsed.query
    if parsed.fragment:
        sanitized += "#" + parsed.fragment

    return sanitized

