def calculate_expression(expr_string: str):
    """
    Safely evaluate a basic arithmetic expression given as a string.

    Raises ValueError for illegal characters, unsupported constructs, parse errors,
    or evaluation problems.
    """
    if not isinstance(expr_string, str):
        raise ValueError("Expression must be a string")

    expr = expr_string.strip()
    if not expr:
        raise ValueError("Empty expression")

    # Quick character-level sanity check to reject potentially dangerous characters early
    if not _ALLOWED_CHARS.fullmatch(expr):
        raise ValueError("Illegal characters in expression")

    # Parse into AST
    try:
        parsed = ast.parse(expr, mode='eval')
    except Exception as e:
        raise ValueError("Failed to parse expression") from e

    # Evaluate AST nodes recursively with strict whitelisting
    def _eval(node):
        # Expression wrapper
        if isinstance(node, ast.Expression):
            return _eval(node.body)

        # Binary operations
        if isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)
            op = node.op
            if isinstance(op, ast.Add):
                return left + right
            if isinstance(op, ast.Sub):
                return left - right
            if isinstance(op, ast.Mult):
                return left * right
            if isinstance(op, ast.Div):
                return left / right
            if isinstance(op, ast.FloorDiv):
                return left // right
            if isinstance(op, ast.Mod):
                return left % right
            if isinstance(op, ast.Pow):
                return left ** right
            raise ValueError("Unsupported binary operator")

        # Unary operations (+ / -)
        if isinstance(node, ast.UnaryOp):
            operand = _eval(node.operand)
            if isinstance(node.op, ast.UAdd):
                return +operand
            if isinstance(node.op, ast.USub):
                return -operand
            raise ValueError("Unsupported unary operator")

        # Numeric literals (ast.Constant for modern Python; ast.Num for older versions)
        if isinstance(node, ast.Constant):
            val = node.value
            # Reject booleans and None; only allow int/float
            if isinstance(val, bool) or val is None:
                raise ValueError("Unsupported constant in expression")
            if isinstance(val, (int, float)):
                return val
            raise ValueError("Unsupported constant type")
        if isinstance(node, ast.Num):  # compatibility for older Python ASTs
            return node.n

        # Everything else is disallowed
        raise ValueError(f"Unsupported expression element: {type(node).__name__}")

    try:
        result = _eval(parsed)
    except ValueError:
        # pass through our ValueErrors
        raise
    except Exception as e:
        # Convert other exceptions (like ZeroDivisionError) into ValueError per spec
        raise ValueError("Evaluation error") from e

    return result

