    """
    Safely evaluate a simple math or logic expression given as a string.
    Returns the string representation of the result, or 'Processing Failed!'
    on any error or if the expression is considered unsafe.
    """
    # Helpers and operator mappings
    binop_map = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
    }
    unaryop_map = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
        ast.Not: operator.not_,
    }
    boolop_map = {
        ast.And: lambda a, b: a and b,
        ast.Or: lambda a, b: a or b,
    }
    cmpop_map = {
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
    }

    # Disallow non-string input
    if not isinstance(formula, str):
        return 'Processing Failed!'

    try:
        expr = ast.parse(formula, mode='eval')
    except Exception:
        return 'Processing Failed!'

    # Evaluate nodes recursively with strict checks
    def eval_node(node):
        # Expression wrapper
        if isinstance(node, ast.Expression):
            return eval_node(node.body)

        # Constants (Python 3.8+)
        if isinstance(node, ast.Constant):
            val = node.value
            if isinstance(val, (int, float, bool)):
                return val
            # Disallow other constant types (str, bytes, None, complex, ...)
            raise ValueError("Disallowed constant type")

        # Compat for older AST nodes
        if isinstance(node, ast.Num):
            return node.n
        if isinstance(node, ast.NameConstant):
            if isinstance(node.value, bool):
                return node.value
            raise ValueError("Disallowed name constant")

        # Names: only allow True/False
        if isinstance(node, ast.Name):
            if node.id == 'True':
                return True
            if node.id == 'False':
                return False
            raise ValueError("Disallowed name")

        # Binary operations
        if isinstance(node, ast.BinOp):
            if type(node.op) not in binop_map:
                raise ValueError("Disallowed binary operator")
            left = eval_node(node.left)
            right = eval_node(node.right)

            # Prevent extremely large exponents to avoid resource abuse
            if isinstance(node.op, ast.Pow):
                # only allow reasonable exponent magnitudes
                if (isinstance(right, (int, float)) and abs(right) > 50) or (not isinstance(right, (int, float))):
                    raise ValueError("Exponent out of allowed range")

            func = binop_map[type(node.op)]
            return func(left, right)

        # Unary operations
        if isinstance(node, ast.UnaryOp):
            if type(node.op) not in unaryop_map:
                raise ValueError("Disallowed unary operator")
            operand = eval_node(node.operand)
            func = unaryop_map[type(node.op)]
            return func(operand)

        # Boolean operations (and/or) - short-circuit style
        if isinstance(node, ast.BoolOp):
            if type(node.op) not in boolop_map:
                raise ValueError("Disallowed boolean operator")
            values = [eval_node(v) for v in node.values]
            result = values[0]
            for v in values[1:]:
                result = boolop_map[type(node.op)](result, v)
            return result

        # Comparisons (support chaining)
        if isinstance(node, ast.Compare):
            left = eval_node(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                if type(op) not in cmpop_map:
                    raise ValueError("Disallowed comparison operator")
                right = eval_node(comparator)
                if not cmpop_map[type(op)](left, right):
                    return False
                left = right
            return True

        # Anything else is disallowed
        raise ValueError("Disallowed expression element")

    try:
        result = eval_node(expr)
        # Final result must be a number or bool
        if not isinstance(result, (int, float, bool)):
            return 'Processing Failed!'
        return str(result)
    except Exception:
        return 'Processing Failed!'

