def format_string(string: str) -> str:
    try:
        userinfo = UserInfo()

        class _SafeUserInfoProxy:
            def __init__(self, ui):
                # store only allowed attribute internally
                object.__setattr__(self, "_user_name", ui.user_name)

            def __getattribute__(self, name):
                # allow only the explicit safe attribute
                if name == "user_name":
                    return object.__getattribute__(self, "_user_name")
                # block access to anything else (including dunder names)
                raise AttributeError("Access to attribute '{}' is denied".format(name))

            def __setattr__(self, name, value):
                raise AttributeError("Modification not allowed")

        safe_userinfo = _SafeUserInfoProxy(userinfo)
        # Only expose the safe proxy under the name 'userinfo'
        return string.format(userinfo=safe_userinfo)
    except Exception as e:
        raise ValueError(str(e))

